contractOracle:
{
  "acs": [
    {
      "id": "AC-1",
      "text": "POST /carts creates an empty cart and responds 201 with its id.",
      "outcomes": [
        "201",
        "the response carries the new cart's id",
        "the new cart is empty"
      ]
    },
    {
      "id": "AC-2",
      "text": "POST /carts/{id} with product_id and a quantity from 1 to 99 adds the product (200); adding a product already in the cart increases its quantity by the amount added.",
      "outcomes": [
        "quantity 1 → 200 and the cart contains the product",
        "quantity 99 → 200 and the cart contains the product",
        "adding a product already in the cart → its quantity increases by the amount added"
      ]
    },
    {
      "id": "AC-3",
      "text": "A quantity outside 1–99 is rejected with 422 and an error for the quantity field; the cart is unchanged.",
      "outcomes": [
        "quantity 0 → 422",
        "quantity 100 → 422",
        "the response has an error for the quantity field",
        "the cart is unchanged"
      ]
    },
    {
      "id": "AC-4",
      "text": "On a product page, choosing a quantity and pressing \"Add to cart\" shows \"Product added to shopping cart.\" and the cart icon in the navigation shows the total number of items.",
      "outcomes": [
        "pressing \"Add to cart\" shows \"Product added to shopping cart.\"",
        "the cart icon in the navigation shows the total number of items in the cart"
      ]
    },
    {
      "id": "AC-5",
      "text": "The cart page (checkout step 1) lists each product with its quantity, unit price and line total (price × quantity), and the cart total.",
      "outcomes": [
        "each product in the cart is listed",
        "each listed product shows its quantity and unit price",
        "each listed product shows its line total, equal to price × quantity",
        "the page shows the cart total"
      ]
    },
    {
      "id": "AC-6",
      "text": "DELETE /carts/{id}/product/{productId} removes the product (204); the cart no longer lists it.",
      "outcomes": [
        "204",
        "the cart no longer lists the product"
      ]
    },
    {
      "id": "AC-7",
      "text": "Deleting a cart responds 204 and is idempotent: deleting a cart that was already deleted also responds 204.",
      "outcomes": [
        "deleting a cart → 204",
        "deleting the same cart again → 204"
      ]
    },
    {
      "id": "AC-8",
      "text": "Any request for a cart that does not exist responds 404 with the message \"Cart not found\".",
      "outcomes": [
        "adding a product to a cart that does not exist → 404 with the message \"Cart not found\"",
        "removing a product from a cart that does not exist → 404 with the message \"Cart not found\"",
        "reading a cart that does not exist → 404 with the message \"Cart not found\"",
        "deleting a cart that does not exist → 404 with the message \"Cart not found\" (see G6 for a cart that was already deleted)"
      ]
    }
  ],
  "rules": [
    {
      "id": "R1",
      "text": "The web shop keeps the cart across page views."
    },
    {
      "id": "R2",
      "text": "A quantity added to a cart is from 1 to 99; a quantity outside 1–99 is rejected."
    }
  ],
  "errorModel": [
    {
      "id": "E1",
      "case": "a quantity outside 1–99 is added to a cart; the response has an error for the quantity field and the cart is unchanged",
      "status": 422,
      "body": null
    },
    {
      "id": "E2",
      "case": "any request for a cart that does not exist",
      "status": 404,
      "body": "Cart not found"
    }
  ],
  "oracleGaps": [
    {
      "id": "G6",
      "resolution": "assumed",
      "value": "The specific criterion is an exception to the general one: deleting a cart that was already deleted responds 204 (AC-7); every other request for a cart that does not exist responds 404 with \"Cart not found\" (AC-8). Reason: AC-7 names this case explicitly and calls deletion idempotent, which a 404 on the second delete would contradict."
    },
    {
      "id": "G7",
      "resolution": "assumed",
      "value": "the sum of the quantities of all products in the cart (a quantity chosen on the product page adds that many items)"
    },
    {
      "id": "G8",
      "resolution": "assumed",
      "value": "the cart total is the sum of the line totals of the products listed"
    }
  ]
}
